import React from "react";
import _ from "lodash";

import "../assets/css/loading-page.css";

function LoadingPage(props) {
  let radius = 150;

  let width = 30;
  let height = 30;

  let numPoints = 10;

  let x = window.outerWidth / 2 - radius - width / 2;
  let y = window.outerHeight / 2 - height / 2;

  return (
    <div className="loading-page-wrapper">
      <h1 className="loading-text-wrapper montserrat-light">loading</h1>
      {_.times(numPoints, n => {
        const firstPointX = radius * Math.cos((2 * Math.PI) / numPoints);
        const firstPointY = radius * Math.cos((2 * Math.PI) / numPoints);
        const secondPointX = radius * Math.cos((2 * Math.PI) / numPoints);
        const secondPointY = radius * Math.cos((2 * Math.PI) / numPoints);

        return (
          <div
            className="circle"
            style={{
              offsetPath: `path("M ${x}, ${
                y - height / 2
              } a ${radius},${radius} 0 1,0 ${
                radius * 2
              },0 a ${radius},${radius} 0 1,0 -${radius * 2},0")`
            }}
          ></div>
        );
      })}
    </div>
  );
}

export default LoadingPage;
